#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — Armarium on fire-nation.
# Run from the dotfiles root on the Mac, on the branch that adds the armarium service:
#   bash systems/x86_64-linux/fire-nation/scripts/armarium-setup.sh
# Values go into the sops file (never into .env); services/books.nix reads them as armarium/* keys.
# ──────────────────────────────────────────────────────────────────────────

SECRETS="systems/x86_64-linux/fire-nation/secrets/secrets.yaml"
POCKET_ID="https://firenation.app"
ABS="https://bookshelf.firenation.app"
ARMARIUM_URL="https://armarium.firenation.app"
WRITTEN_SOPS=()

# set_sops KEY VALUE — upsert armarium/KEY in the sops file. Idempotent; the value is JSON-quoted.
set_sops() {
  local key="$1" value="$2" json
  json=$(printf '%s' "$value" | python3 -c 'import json,sys; print(json.dumps(sys.stdin.read()))')
  if sops set "$SECRETS" "[\"armarium\"][\"$key\"]" "$json" >/dev/null; then
    WRITTEN_SOPS+=("armarium/$key")
    printf '  %s✓ wrote%s armarium/%s → %s\n' "$GREEN" "$RESET" "$key" "$SECRETS"
  else
    SKIPPED+=("sops key armarium/$key")
    warn "could not write armarium/$key with sops"
  fi
}

# has_sops KEY — true if armarium/KEY already exists in the sops file.
has_sops() {
  sops --decrypt --extract "[\"armarium\"][\"$1\"]" "$SECRETS" >/dev/null 2>&1
}

[[ -f "$SECRETS" ]] || { printf '%sRun this from the dotfiles root (%s not found).%s\n' "$RED" "$SECRETS" "$RESET"; exit 1; }
command -v sops >/dev/null || { printf '%ssops is required (brew install sops).%s\n' "$RED" "$RESET"; exit 1; }

TOTAL_STAGES=9

banner "Armarium on fire-nation"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Pocket ID — groups"
say "Armarium uses the groups you already have: 'citizens' are members, 'admin' are admins."
say "Nothing to create. Just make sure the people you expect are in them."
open_url "$POCKET_ID/settings/admin/user-groups"
step "Administration → User Groups → 'admin' contains you."
step "'citizens' contains you and every friend who should be able to add books."
pause "Done? Press Enter."

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Pocket ID — OIDC client"
say "Armarium signs people in through Pocket ID with its own client."
open_url "$POCKET_ID/settings/admin/oidc-clients"
step "Administration → OIDC Clients → Add OIDC Client."
step "Name: Armarium.  Client type: confidential (the default)."
step "Callback URL:  $ARMARIUM_URL/auth/callback"
step "Create. The client page shows the Client ID and, once only, the Client secret."
step "Then open the client's Access tab → Allowed User Groups → Selected user groups → tick 'citizens' and 'admin'."
REPLACE_OIDC=1
if has_sops oidc-client-secret; then
  note "armarium/oidc-client-id and oidc-client-secret already exist in sops."
  confirm "Replace them?" || REPLACE_OIDC=0
fi
if (( REPLACE_OIDC )); then
  ask OIDC_CLIENT_ID "Paste the Client ID:"
  ask_secret OIDC_CLIENT_SECRET "Paste the Client secret (hidden):"
  set_sops oidc-client-id "$OIDC_CLIENT_ID"
  set_sops oidc-client-secret "$OIDC_CLIENT_SECRET"
fi

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Audiobookshelf — API key and library"
say "Armarium dedupes against the library and asks Audiobookshelf to scan and match new books."
open_url "$ABS/config/users"
step "Settings → Users → API Keys → Create API Key."
step "Name: Armarium.  User: your admin user (the key inherits its permissions). Leave it active, no expiry."
step "Save; the key is shown once."
ask_secret ABS_API_KEY "Paste the API key (hidden):"
say "Checking the key against $ABS …"
if LIBS=$(curl -fsS -H "Authorization: Bearer $ABS_API_KEY" "$ABS/api/libraries" 2>/dev/null); then
  printf '%s' "$LIBS" | python3 -c '
import json,sys
libs=[l for l in json.load(sys.stdin).get("libraries",[]) if l.get("mediaType")=="book"]
for i,l in enumerate(libs,1):
    folders=", ".join(f.get("fullPath","") for f in l.get("folders",[]))
    print("  %d. %s  (%s)  %s" % (i, l.get("name",""), l.get("id",""), folders))
'
  ask ABS_LIBRARY_PICK "Number of the library Armarium should fill (the one at /audiobooks):"
  ABS_LIBRARY_ID=$(printf '%s' "$LIBS" | python3 -c "
import json,sys
libs=[l for l in json.load(sys.stdin).get('libraries',[]) if l.get('mediaType')=='book']
print(libs[int('$ABS_LIBRARY_PICK')-1]['id'])")
  say "Library id: $ABS_LIBRARY_ID"
else
  warn "Audiobookshelf refused the key or isn't reachable from here."
  ask ABS_LIBRARY_ID "Paste the library id by hand (from the library's URL in Audiobookshelf):"
fi
set_sops abs-api-key "$ABS_API_KEY"
set_sops abs-library-id "$ABS_LIBRARY_ID"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Discord — webhook for the shelf channel"
say "New books, failed downloads, re-login nudges and an hourly digest of pending approvals."
open_url "https://discord.com/channels/@me"
step "In your server: create or pick a channel (e.g. #shelf)."
step "Channel settings → Integrations → Webhooks → New Webhook → name it Armarium → Copy Webhook URL."
if has_sops discord-webhook && ! confirm "armarium/discord-webhook exists. Replace it?"; then
  note "keeping the existing webhook"
else
  ask_secret DISCORD_WEBHOOK_URL "Paste the webhook URL (hidden):"
  set_sops discord-webhook "$DISCORD_WEBHOOK_URL"
fi

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Keys only Armarium needs"
say "LIBATION_MASTER_KEY encrypts every member's Audible tokens at rest; ARMARIUM_SESSION_SECRET signs"
say "the login cookie. Both are generated here. Losing the master key means everyone signs in again."
if has_sops libation-master-key; then
  note "armarium/libation-master-key exists; keeping it (replacing it would lock out every connected account)."
else
  set_sops libation-master-key "$(openssl rand -base64 32)"
fi
if has_sops session-secret; then
  note "armarium/session-secret exists; keeping it."
else
  set_sops session-secret "$(openssl rand -base64 32)"
fi
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "GitHub — make the image pullable"
say "The repo is private, so its container package is private too. fire-nation has a ghcr login, but"
say "a public image is simpler and nothing secret is baked into it."
open_url "https://github.com/users/r0adkll/packages/container/armarium/settings"
step "Danger zone → Change visibility → Public → confirm."
note "If the package page 404s, CI hasn't published yet: check https://github.com/r0adkll/armarium/actions"
pause "Done? Press Enter."

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "fire-nation — retire the old libation service"
say "The old downloader's state (your Audible tokens and its database) is no longer used; Armarium keeps"
say "its own under /mnt/data/armarium/users. You chose to delete it."
if confirm "Delete /mnt/home/stacks/libation on fire-nation now? (asks for your sudo password)"; then
  ssh -t fire-nation 'sudo rm -rf /mnt/home/stacks/libation && echo removed' || warn "could not remove it; do it by hand later"
else
  SKIPPED+=("sudo rm -rf /mnt/home/stacks/libation on fire-nation")
fi

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Deploy — DNS record and the testing branch"
say "armarium.firenation.app needs one proxied A record, then the testing branch deploys without a boot entry."
say "Preview of DNS changes:"
nix run .#dns -- preview || warn "preview failed; run it by hand"
if confirm "Push the DNS change?"; then
  nix run .#dns -- push || warn "push failed; run it by hand"
else
  SKIPPED+=("nix run .#dns -- push")
fi
say "Committing the secrets alongside the service, then pushing testing-fire-nation."
git add "$SECRETS" systems/x86_64-linux/fire-nation/services/books.nix systems/x86_64-linux/fire-nation/scripts/armarium-setup.sh
git commit -q -m "fire-nation: add armarium, retire libation" || note "nothing new to commit"
if confirm "Push to testing-fire-nation now? comin deploys it within about a minute."; then
  git push -f origin HEAD:testing-fire-nation
  say "Waiting for comin and the service…"
  for _ in $(seq 1 40); do
    if ssh fire-nation 'systemctl --user is-active armarium' 2>/dev/null | grep -q '^active'; then break; fi
    sleep 10
  done
  ssh fire-nation 'systemctl --user is-active armarium; podman logs --tail 40 armarium 2>&1 | grep -E "listening|ERROR|WARN" | tail -8' || true
  say "Route check:"
  ssh fire-nation "curl -s -o /dev/null -w 'https://armarium.firenation.app -> %{http_code}\n' --resolve armarium.firenation.app:443:127.0.0.1 https://armarium.firenation.app/healthz" || true
else
  SKIPPED+=("git push origin HEAD:testing-fire-nation")
fi

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "First book, end to end"
open_url "$ARMARIUM_URL"
step "Sign in with Pocket ID. The sidebar footer should say '… · admin'."
step "Audible accounts → Connect an account → follow the Amazon sign-in and paste the landing URL back."
step "My books → pick one title → Add to shelf. As admin it is approved on the spot."
step "Home → 'On the way' walks through Download, Shelve, Match. A Discord post arrives when it lands."
step "Open Audiobookshelf: the book is under Author/Series/N - Title [ASIN] with Audible metadata."
pause "When the book is on the shelf, press Enter."
if confirm "Land this on main now? (deploys the boot entry; otherwise do it later with git)"; then
  git checkout -q main && git merge -q --ff-only armarium && git push -q origin main
  say "Landed. comin will switch main within a minute."
else
  SKIPPED+=("merge branch armarium into main and push")
fi

finish
(( ${#WRITTEN_SOPS[@]} )) && note "wrote ${#WRITTEN_SOPS[@]} sops key(s): ${WRITTEN_SOPS[*]}"
